from bagimlilik import kurulum_sirasi, DonguHatasi

def test_kurulum_sirasi():
    print("Running tests...")

    # Test 1: Basit sıralama ve alfabetik öncelik
    deps1 = {"a": ["c"], "b": ["c"], "c": []}
    assert kurulum_sirasi(deps1) == ["c", "a", "b"]

    # Test 2: Karmaşık sıralama
    deps2 = {"a": ["b", "c"], "b": ["d"], "c": ["d"], "d": []}
    assert kurulum_sirasi(deps2) == ["d", "b", "c", "a"]

    # Test 3: Basit döngü (kendine bağımlı)
    deps3 = {"a": ["a"]}
    try:
        kurulum_sirasi(deps3)
        assert False, "Test 3 failed: No error for self-loop"
    except DonguHatasi as e:
        assert e.dongu == ["a"]

    # Test 4: Karmaşık döngü a -> b -> c -> a
    deps4 = {"a": ["b"], "b": ["c"], "c": ["a"], "d": ["a"]}
    try:
        kurulum_sirasi(deps4)
        assert False, "Test 4 failed: No error for loop"
    except DonguHatasi as e:
        assert e.dongu == ["a", "b", "c"]

    # Test 5: Sadece bağımlılık olarak geçenler
    deps5 = {"a": ["b"]}
    assert kurulum_sirasi(deps5) == ["b", "a"]

    # Test 6: Aynı bağımlılık iki kez
    deps6 = {"a": ["b", "b"], "b": []}
    assert kurulum_sirasi(deps6) == ["b", "a"]

    # Test 7: Çoklu döngülerden birini yakalama
    # a < b < c < d. döngü b-c-d
    deps7 = {"a": ["b"], "b": ["c"], "c": ["d"], "d": ["b"]}
    try:
        kurulum_sirasi(deps7)
    except DonguHatasi as e:
        # Döngü b-c-d'dir. En küçük b.
        assert e.dongu == ["b", "c", "d"]

    print("All tests passed!")

if __name__ == "__main__":
    try:
        test_kurulum_sirasi()
    except Exception as e:
        print(f"Tests failed: {e}")
        import traceback
        traceback.print_exc()
        sys.exit(1)

