def kurulum_sirasi(deps: dict[str, list[str]]) -> list[str]:
    """
    Bağımlılıkları çözer ve kurulum sırasını döndürür.
    Döngü varsa DonguHatasi fırlatır.
    """
    # 1. Tüm paketleri belirle (deps içindekiler + bağımlılık olarak geçenler)
    all_packages = set(deps.keys())
    for requirements in deps.values():
        for req in requirements:
            all_packages.add(req)

    # 2. Döngü kontrolü (DFS)
    # Graph yapısı: paket -> bağımlılık (u'nun v'ye bağımlılığı var)
    adj_orig = {p: set() for p in all_packages}
    for package, requirements in deps.items():
        for req in requirements:
            adj_orig[package].add(req)

    visited = {} # 0: unvisited, 1: visiting, 2: visited

    def find_cycle_dfs(u, parent_map):
        visited[u] = 1
        for v in adj_orig[u]:
            if visited.get(v, 0) == 1:
                # Döngü bulundu: v -> ... -> u -> v
                cycle = []
                curr = u
                while curr != v:
                    cycle.append(curr)
                    curr = parent_map[curr]
                cycle.append(v)
                cycle.reverse()
                # Alfabetik en küçüğü bul ve döngüyü oradan başlat
                min_node = min(cycle)
                idx = cycle.index(min_node)
                return cycle[idx:] + cycle[:idx]
            elif visited.get(v, 0) == 0:
                parent_map[v] = u
                res = find_cycle_dfs(v, parent_map)
                if res:
                    return res
        visited[u] = 2
        return None

    for node in sorted(all_packages):
        if visited.get(node, 0) == 0:
            cycle_res = find_cycle_dfs(node, {})
            if cycle_res:
                raise DonguHatasi(cycle_res)

    # 3. Topolojik Sıralama (Kahn's Algorithm)
    # Graph yapısı: bağımlılık -> paket (req -> package, req kurulmadan package kurulmaz)
    adj_topo = {p: set() for p in all_packages}
    in_degree = {p: 0 for p in all_packages}

    for package, requirements in deps.items():
        unique_reqs = set(requirements)
        for req in unique_reqs:
            if req in all_packages:
                if package not in adj_topo[req]:
                    adj_topo[req].add(package)
                    in_degree[package] += 1

    import heapq
    # Kuyruk alfabetik sıralama için min-heap kullanır
    queue = [p for p in all_packages if in_degree[p] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
